public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        String profile = sc.nextLine().trim();
        int n = Integer.parseInt(sc.nextLine().trim());
        List<String> config = new ArrayList<>();
        for (int i = 0; i < n; i++) config.add(sc.nextLine().trim());
        int m = Integer.parseInt(sc.nextLine().trim());
        List<String> log = new ArrayList<>();
        for (int i = 0; i < m; i++) log.add(sc.nextLine());

        if (profile.equals("prod")) {
            System.out.println("PROD_PROFILE");
            return;
        }
        for (String line : config) {
            if (line.startsWith("quarkus.datasource.jdbc.url=")) {
                System.out.println("URL_CONFIGURED");
                return;
            }
        }
        for (String line : log) {
            if (line.contains("container runtime")) {
                System.out.println("NO_CONTAINER_RUNTIME");
                return;
            }
        }
        System.out.println("STARTED");
    }
}

