import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        String requirement = sc.nextLine().trim();
        int n = Integer.parseInt(sc.nextLine().trim());
        boolean unsupported = false, needsConfig = false;
        for (int i = 0; i < n; i++) {
            String state = sc.nextLine().trim().split("\\s+")[1];
            if (state.equals("UNSUPPORTED")) unsupported = true;
            if (state.equals("NEEDS_CONFIG")) needsConfig = true;
        }
        if (unsupported) System.out.println("JVM unsupported-library");
        else if (requirement.equals("LONG_RUNNING")) System.out.println("JVM long-running-workload");
        else if (needsConfig) System.out.println("NATIVE needs-config");
        else System.out.println("NATIVE ready");
    }
}

