import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        List<String> imports = new ArrayList<>();
        for (int i = 0; i < n; i++) imports.add(sc.nextLine().trim());
        boolean checked = Boolean.parseBoolean(sc.nextLine().trim());

        Collections.sort(imports);
        boolean rewrite = false;
        for (String line : imports) {
            String target = line.substring(line.indexOf(' ') + 1);   // import の後ろ
            String verdict;
            if (target.startsWith("jakarta.")) {
                verdict = "NATIVE_API";
            } else if (target.startsWith("org.springframework.")) {
                verdict = checked ? "COMPAT_EXTENSION" : "SPIKE";
            } else {
                verdict = "REWRITE";
                rewrite = true;
            }
            System.out.println(verdict + " " + line);
        }
        System.out.println(rewrite ? "PLAN rewrite-required" : "PLAN incremental");
    }
}

