            String profile = sc.nextLine().trim();
            boolean configured = false;
            for (String line : config) {
                if (line.startsWith(key) || line.startsWith("%" + profile + "." + key)) {
                    configured = true;
                    break;
                }
            }
            String verdict;
            if (configured) verdict = "EXPLICIT";
            else if (profile.equals("prod")) verdict = "MISCONFIGURED";
            else verdict = "DEV_SERVICES";
            System.out.println(profile + ":" + verdict);
        }
    }
}

