import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        List<String> log = new ArrayList<>();
        for (int i = 0; i < n; i++) log.add(sc.nextLine());
        boolean useNative = Boolean.parseBoolean(sc.nextLine().trim());

        List<String> todo = new ArrayList<>();
        if (contains(log, "Manual migration required")) todo.add("MANUAL_MIGRATION");
        if (!contains(log, "JVM tests: PASSED")) todo.add("JVM_TEST");
        if (useNative && !contains(log, "Native tests: PASSED")) todo.add("NATIVE_TEST");

        for (String item : todo) System.out.println("TODO " + item);
        System.out.println(todo.isEmpty() ? "RELEASE" : "HOLD");
    }

    static boolean contains(List<String> log, String needle) {
        for (String line : log) {
            if (line.contains(needle)) return true;
        }
        return false;
    }
}
